-- 54 Tesla Lab: every line here is a `line`, reshaped with Line.set.
-- The lightning is a jagged path rebuilt each flicker; the laser is traced
-- through the turning mirrors by reflection, and its bend points handed over
-- every frame. Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/54-tesla-lab.scene"
local COILS = { { -470.0, -250.0 }, { -150.0, -250.0 } }
local MIRRORS = { { 220.0, 60.0, 0.7854 }, { 220.0, -150.0, 0.7854 }, { 540.0, -150.0, -0.7854 }, { 540.0, 230.0, 0.7854 } }
local EMITTER = { -60.0, 60.0 }
local MIRROR_HALF = 60
local captions = true
local arcing = true
local t, flicker, spin = 0, 0, 0
local bolts, mirrors, coil_lights, coil_glows = {}, {}, {}, {}
local beam, halo, hit_light, hit_glow, status

function init(entity)
    for k = 1, 3 do bolts[k] = Entity.find_by_name("Bolt" .. k) end
    for i = 1, #MIRRORS do mirrors[i] = Entity.find_by_name("Mirror" .. i) end
    for i = 1, 2 do
        coil_lights[i] = Entity.find_by_name("CoilLight" .. i)
        coil_glows[i] = Entity.find_by_name("CoilGlow" .. i)
    end
    beam = Entity.find_by_name("Beam")
    halo = Entity.find_by_name("BeamHalo")
    hit_light = Entity.find_by_name("HitLight")
    hit_glow = Entity.find_by_name("HitGlow")
    status = Entity.find_by_name("Status")
end

-- A jagged bolt from a to b: midpoints pushed sideways, less each halving.
local function bolt(ax, ay, bx, by, rough)
    local pts = { { ax, ay }, { bx, by } }
    for _ = 1, 5 do
        local out = { pts[1] }
        for i = 1, #pts - 1 do
            local p, q = pts[i], pts[i + 1]
            local dx, dy = q[1] - p[1], q[2] - p[2]
            local len = math.sqrt(dx * dx + dy * dy)
            local push = (math.random() - 0.5) * rough * len
            out[#out + 1] = { (p[1] + q[1]) / 2 - dy / len * push, (p[2] + q[2]) / 2 + dx / len * push }
            out[#out + 1] = q
        end
        pts = out
    end
    return pts
end

-- Where a ray from (x, y) along (dx, dy) first meets a mirror: the distance,
-- and the mirror's normal there; nil when it meets none.
local function nearest_mirror(x, y, dx, dy, skip)
    local best, bnx, bny, bi
    for i, m in ipairs(MIRRORS) do
        if i ~= skip then
            local a = m.angle
            local ux, uy = -math.sin(a), math.cos(a)      -- along the mirror
            local nx, ny = math.cos(a), math.sin(a)       -- its normal
            local den = dx * nx + dy * ny
            if math.abs(den) > 1e-4 then
                local d = ((m[1] - x) * nx + (m[2] - y) * ny) / den
                if d > 1 then
                    local hx, hy = x + dx * d, y + dy * d
                    local along = (hx - m[1]) * ux + (hy - m[2]) * uy
                    if math.abs(along) <= MIRROR_HALF and (best == nil or d < best) then
                        best, bnx, bny, bi = d, nx, ny, i
                    end
                end
            end
        end
    end
    return best, bnx, bny, bi
end

function update(entity, dt)
    nav.tick(SCENE)
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if Input.is_key_just_pressed("Space") then arcing = not arcing end
    t = t + dt
    if Input.is_key_pressed("Left") then spin = spin + dt end
    if Input.is_key_pressed("Right") then spin = spin - dt end

    -- The lightning: rebuilt every few frames, a different shape each time.
    flicker = flicker - dt
    if flicker <= 0 then
        flicker = 0.05 + math.random() * 0.05
        local a, b = COILS[1], COILS[2]
        for k, e in ipairs(bolts) do
            if e then
                if arcing then
                    Line.set(e, "points", bolt(a[1] + 10, a[2] + 255, b[1] - 10, b[2] + 255, 0.45 + 0.1 * k))
                else
                    Line.set(e, "points", { { 0, -9999 }, { 1, -9999 } })
                end
            end
        end
        local k = arcing and (1.0 + math.random() * 1.2) or 0.15
        for i = 1, 2 do
            if coil_lights[i] then Lighting.set_intensity(coil_lights[i], k) end
            if coil_glows[i] then Sprite.set_color(coil_glows[i], 0.9 * k, 1.1 * k, 1.5 * k, 0.5) end
        end
    end

    -- The mirrors turn slowly; the beam is traced through them.
    for i, m in ipairs(MIRRORS) do
        m.angle = m[3] + 0.025 * math.sin(t * 0.4 + i * 1.7) + spin
        if mirrors[i] then Transform.set_rotation(mirrors[i], m.angle) end
    end
    local x, y = EMITTER[1] + 45, EMITTER[2]
    local dx, dy = 1, 0
    local pts = { { x, y } }
    local skip
    for _ = 1, 8 do
        local d, nx, ny, i = nearest_mirror(x, y, dx, dy, skip)
        if not d then
            x, y = x + dx * 2000, y + dy * 2000
            pts[#pts + 1] = { x, y }
            break
        end
        x, y = x + dx * d, y + dy * d
        pts[#pts + 1] = { x, y }
        local dot = dx * nx + dy * ny
        dx, dy = dx - 2 * dot * nx, dy - 2 * dot * ny
        skip = i
    end
    if beam then Line.set(beam, "points", pts) end
    if halo then Line.set(halo, "points", pts) end
    -- The glow sits where the beam last struck a mirror.
    local last = pts[math.max(1, #pts - 1)]
    if hit_light then Transform.set_position(hit_light, last[1], last[2]) end
    if hit_glow then Transform.set_position(hit_glow, last[1], last[2]) end
    if status then
        UI.set_text(status, "laser: " .. (#pts - 2) .. " bounce" .. ((#pts - 2) == 1 and "" or "s")
            .. "   lightning " .. (arcing and "on" or "off"))
    end
end
